package com.rpb.reservation.workforce;
import com.fasterxml.jackson.databind.ObjectMapper;import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.attendance.*;import com.rpb.reservation.workforce.attendance.daily.*;import com.rpb.reservation.workforce.attendancepolicy.*;import com.rpb.reservation.workforce.approval.*;import com.rpb.reservation.workforce.calendar.*;import com.rpb.reservation.workforce.leave.*;import com.rpb.reservation.workforce.scheduling.*;import com.rpb.reservation.workforce.workmode.*;import com.rpb.reservation.walkin.api.CurrentActor;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;import static com.rpb.reservation.workforce.attendance.daily.AttendanceDailyDtos.*;import static com.rpb.reservation.workforce.attendancepolicy.AttendancePolicyDtos.*;
class WorkforceAttendanceNormalEvaluationPostgresTest extends WorkforcePostgresTest {
 AttendanceDailyService daily;AttendanceExceptionService exceptions;AttendanceDailyRepository days;AttendancePolicyRepository policies;AttendancePolicyResolver resolver;SchedulingRepository schedules;UUID employee,employeeAccount;CurrentActor worker;WorkforceAttendancePostgresTest.MutableClock time;WorkforceJson json;
 @BeforeEach void setupDaily(TestInfo info){if(info.getTestMethod().map(m->m.getDeclaringClass()!=WorkforceAttendanceNormalEvaluationPostgresTest.class).orElse(false))return;json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());time=new WorkforceAttendancePostgresTest.MutableClock();time.at("2026-11-03T12:00:00Z");var audit=new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules());employeeAccount=account("store_staff",Set.of(store,sibling),Set.of("workforce.view"));employee=UUID.randomUUID();employees.save(admin,store,employee,command(0,List.of(store,sibling),company,employeeAccount,null));worker=new CurrentActor(tenant,employeeAccount,"staff",Set.of("store_staff"),Set.of("workforce.view"),Set.of(store,sibling));policies=new AttendancePolicyRepository(jdbc,json);resolver=new AttendancePolicyResolver(policies,repository,new WorkModeRepository(jdbc,json));days=new AttendanceDailyRepository(jdbc,json);schedules=new SchedulingRepository(jdbc,json);var ar=new ApprovalRepository(jdbc,json);var source=new ApprovalSources(new AttendanceRepository(jdbc,json),new LeaveRepository(jdbc),new CalendarRepository(jdbc),json,time);daily=proxy(new AttendanceDailyService(resolver,policies,days,schedules,source,ar,repository,access,json,audit,time));exceptions=proxy(new AttendanceExceptionService(access,repository,schedules,policies,days,new LeaveTypeRepository(jdbc),ar,audit,time));}
 void policy(String mode){policies.insert(tenant,adminId,new PolicyVersion(UUID.randomUUID(),employee,company,store,LocalDate.of(2026,10,1),mode,"personal",null,0,new Arrangement(List.of(1,2,3,4,5),LocalTime.of(9,0),480,60,180),"Asia/Singapore",1));}
 LocalDate date(){return LocalDate.of(2026,11,2);} EffectiveDay day(){return daily.capture(tenant,company,employee,date(),date()).getFirst();}
 @Test void automaticConcurrentRunsAppendOneSystemVersionAndKeepNullActor()throws Exception{
  policy("default_normal");realAudit(false);var normal=normal();var scope=new AttendanceNormalEvaluationRepository.Scope(tenant,store,company,employee,"Asia/Singapore");
  var pool=java.util.concurrent.Executors.newFixedThreadPool(2);var start=new java.util.concurrent.CountDownLatch(1);
  try{var jobs=new ArrayList<java.util.concurrent.Future<?>>();for(int n=0;n<2;n++)jobs.add(pool.submit(()->{try{start.await();normal.evaluate(scope);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}}));start.countDown();for(var job:jobs)job.get(25,java.util.concurrent.TimeUnit.SECONDS);}finally{pool.shutdownNow();}
  assertThat(jdbc.queryForObject("select count(*) from workforce_attendance_day_versions v join workforce_attendance_days d on d.tenant_id=v.tenant_id and d.id=v.day_id where d.tenant_id=? and d.employee_id=? and d.work_date=?",Long.class,tenant,employee,date())).isEqualTo(1);
  assertThat(jdbc.queryForObject("select count(*) from workforce_attendance_day_versions where tenant_id=? and initiator_kind='system' and actor_id is null",Long.class,tenant)).isGreaterThan(0);
  assertThat(day().state()).isEqualTo("system_valid");assertThat(day().actualSeconds()).isNull();assertThat(day().workSeconds()).isEqualTo(28800);
  var scopes=new AttendanceNormalEvaluationRepository(jdbc,json).scopes("",100);assertThat(scopes).anyMatch(s->s.tenant().equals(tenant)&&s.employee().equals(employee));
 }
 @Test void systemEvaluationKeepsManagerPendingAndHumanApprovalStable(){policy("default_normal");jdbc.update("insert into auth_account_roles(account_id,role_code) values(?,'store_manager')",employeeAccount);var normal=normal();var scope=new AttendanceNormalEvaluationRepository.Scope(tenant,store,company,employee,"Asia/Singapore");normal.evaluate(scope);var before=day();assertThat(before.state()).isEqualTo("pending");assertThat(before.issues()).contains("WORKFORCE_MANAGER_ADMIN_REVIEW");daily.review(admin,store,before.sourceId(),new DayReviewWrite(employee,company,date(),before.version(),before.sourceFingerprint(),"HQ"));normal.evaluate(scope);assertThat(day().state()).isEqualTo("human_valid");assertThat(day().version()).isEqualTo(before.version()+1);}
 @Test void automaticAuditUsesDatabaseContractAndCommitsIdempotently(){
  policy("default_normal");realAudit(false);var normal=normal();var scope=new AttendanceNormalEvaluationRepository.Scope(tenant,store,company,employee,"Asia/Singapore");
  int created=normal.evaluate(scope);assertThat(created).isGreaterThan(0);assertThat(normal.evaluate(scope)).isZero();
  assertThat(jdbc.queryForObject("select count(*) from audit_logs where tenant_id=? and store_id=? and operation_code='workforce.attendance.evaluate' and source='system' and actor_type='system' and actor_id is null",Long.class,tenant,store)).isEqualTo(created);
  assertThat(jdbc.queryForObject("select count(*) from workforce_attendance_day_versions where tenant_id=? and initiator_kind='system'",Long.class,tenant)).isEqualTo(created);
 }
 @Test void auditFailureRollsBackBothDatabaseAuditAndSystemVersions(){
  policy("default_normal");realAudit(true);var normal=normal();var scope=new AttendanceNormalEvaluationRepository.Scope(tenant,store,company,employee,"Asia/Singapore");
  assertThatThrownBy(()->normal.evaluate(scope)).isInstanceOf(IllegalStateException.class).hasMessage("after_real_audit_insert");
  assertThat(jdbc.queryForObject("select count(*) from audit_logs where tenant_id=?",Long.class,tenant)).isZero();
  assertThat(jdbc.queryForObject("select count(*) from workforce_attendance_day_versions where tenant_id=?",Long.class,tenant)).isZero();
  assertThat(jdbc.queryForObject("select count(*) from workforce_attendance_days where tenant_id=?",Long.class,tenant)).isZero();
 }
 void realAudit(boolean failAfterInsert){org.mockito.Mockito.doAnswer(call->{
  com.rpb.reservation.common.scope.StoreScope scope=call.getArgument(0);com.rpb.reservation.audit.domain.AuditLog log=call.getArgument(1);
  jdbc.update("insert into audit_logs(id,tenant_id,store_id,operation_code,target_type,target_id,source,actor_type,actor_id,metadata) values(?,?,?,?,?,?,?,?,?,?::jsonb)",log.id(),scope.tenantId().value(),scope.storeId().value(),log.operationCode(),log.targetType(),log.targetId(),log.source(),log.actorType(),log.actorId(),log.metadata());
  if(failAfterInsert)throw new IllegalStateException("after_real_audit_insert");return log;
 }).when(logs).append(org.mockito.ArgumentMatchers.any(com.rpb.reservation.common.scope.StoreScope.class),org.mockito.ArgumentMatchers.any(com.rpb.reservation.audit.domain.AuditLog.class));}
 AttendanceNormalEvaluationService normal(){org.mockito.Mockito.when(gate.evaluateCommercial("workforce",tenant,store)).thenReturn(com.rpb.reservation.appgate.domain.AppGateDecision.allow("workforce",tenant,store,null));return proxy(new AttendanceNormalEvaluationService(new AttendanceNormalEvaluationRepository(jdbc,json),days,daily,new ApprovalRepository(jdbc,json),repository,gate,logs,json,time));}
}
